const fs = require('fs');
const path = require('path');
const glob = require('glob');
const { optimize } = require('svgo');
const { parse } = require('node-html-parser');

// 以本文件所在目录（仓库根）为基准定位，避免依赖运行时 cwd
const ROOT = __dirname;
const SRC_DIR = path.join(ROOT, 'zhi2-web-admin', 'public', 'assets', 'images', 'svg');
const SPRITE_OUT = path.join(ROOT, 'zhi2-web-admin', 'public', 'assets', 'images', 'sprite.svg');
const ICONS_JS_OUT = path.join(ROOT, 'icons.js');

// 仅做颜色转换（fill -> currentColor），保持图标的可着色能力
const svgoPlugins = [{ name: 'convertColors', params: { currentColor: true } }];

// 获取所有 SVG 文件
const svgFiles = glob.sync(path.join(SRC_DIR, '*.svg'));

const symbols = [];
const fileNames = [];
for (const file of svgFiles) {
  const code = fs.readFileSync(file, 'utf-8');
  const optimizedSvg = optimize(code, { plugins: svgoPlugins }).data;
  const svgElement = parse(optimizedSvg).querySelector('svg');
  if (!svgElement) {
    // 解析失败时跳过，避免产出损坏 symbol
    console.warn('[generate-sprite] 跳过无法解析的 SVG:', file);
    continue;
  }
  const fileName = path.basename(file, '.svg');
  fileNames.push(fileName);

  const symbolElement = parse('<symbol/>').querySelector('symbol');
  symbolElement.setAttribute('id', `icon-${fileName}`);
  // 保留源文件真实 viewBox（缺失时兜底 0 0 48 48），避免非 48×48 图标被拉伸变形
  const viewBox = svgElement.getAttribute('viewBox') || '0 0 48 48';
  symbolElement.setAttribute('viewBox', viewBox);
  // 将 SVG 子节点移入 symbol
  svgElement.childNodes.forEach((child) => symbolElement.appendChild(child));
  symbols.push(symbolElement.toString());
}

// 生成 sprite（隐藏 svg 容器）
const svgSprite = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:link="http://www.w3.org/1999/xlink" style="position: absolute; width: 0px; height: 0px;">${symbols.join('\n')}</svg>`;
fs.mkdirSync(path.dirname(SPRITE_OUT), { recursive: true });
fs.writeFileSync(SPRITE_OUT, svgSprite);
fs.writeFileSync(ICONS_JS_OUT, `export const icons = ${JSON.stringify(fileNames)}`);

console.log(`[generate-sprite] 生成 ${symbols.length} 个 symbol -> ${SPRITE_OUT}`);

